```python
def is_scalar_field(field: Field) -> bool:
    return (
        field.shape == Shape.SINGLETON
        and not isinstance(field.type_, type) or not issubclass(field.type_, BaseModel)
        and not isinstance(field.type_, type) or not issubclass(field.type_, sequence_types + (dict,))
        and not isinstance(field.schema, params.Body)
        and not (hasattr(field.type_, '__origin__') and field.type_.__origin__ == Union)
    )
```
